$user=null; $mine=[]; $error=null;
try { if(!empty($_SESSION['user_id'])) { $db=Database::connection(); $user=Authorization::user($db,(int)$_SESSION['user_id']); if($user){$q=$db->prepare('SELECT reference_code,office_unit,appointment_purpose,requested_date,requested_time,status,created_at FROM appointment_requests WHERE user_id=:uid ORDER BY created_at DESC LIMIT 15');$q->execute(['uid'=>$user['user_id']]);$mine=$q->fetchAll(PDO::FETCH_ASSOC);} } } catch(Throwable $e){error_log('Appointment page: '.$e->getMessage());$error='Appointment information is temporarily unavailable.';}
pageHeader('Appointments','Request a meeting with the Barangay San Antonio office.'); ?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">ONLINE SERVICE</p><h1>Request an Appointment</h1><p>Choose your preferred office, date, and time. Your appointment is not confirmed until authorized personnel approve it.</p></div></section><section class="section"><div class="content-layout"><article class="content-panel"><div class="notice info"><b>Scheduling notice</b><p>Available office hours and capacity must be confirmed by the Barangay Hall. Submitting a preferred slot does not reserve it automatically.</p></div>
