<?php if($mine): ?><div class="section-inner"><h2>Your appointment requests</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Purpose</th><th>Date / Time</th><th>Status</th></tr></thead><tbody><?php foreach($mine as $r): ?><tr><td><?= Security::e($r['reference_code']) ?></td><td><?= Security::e($r['appointment_purpose']) ?></td><td><?= Security::e($r['requested_date'].' '.$r['requested_time']) ?></td><td><?= Security::e($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
